contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take all parameters that setL1BlockValues accepts
    function run(
        address caller,
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public payable {
        require(address(this) != address(0));
        // Read all observable fields before the call
        uint64 before_number = c.number();
        uint64 before_timestamp = c.timestamp();
        uint256 before_basefee = c.basefee();
        bytes32 before_hash = c.hash();
        uint64 before_sequenceNumber = c.sequenceNumber();
        bytes32 before_batcherHash = c.batcherHash();
        uint256 before_l1FeeOverhead = c.l1FeeOverhead();
        uint256 before_l1FeeScalar = c.l1FeeScalar();
        address depositor = c.depositorAccount();

        // Attempt call from either depositorAccount or some other address.
        // We simulate calls from another address by forwarding through a small helper contract created on the fly.
        bool reverted;

        if (caller == address(this) || caller == depositor) {
            // call directly as this contract (msg.sender will be InvMutTest)
            // If caller == depositor, then the depositorAccount must equal address(this) for this direct call to be from depositor.
            // Otherwise it's a non-depositor direct call.
            try c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // deploy a transient forwarder that calls c on behalf of `caller` by setting its own address as msg.sender
            // but we cannot control an arbitrary external address here; instead we deploy a Forwarder and use it as a distinct caller
            Forwarder f = new Forwarder();
            try f.callSet(
                c,
                _number,
                _timestamp,
                _basefee,
                _hash,
                _sequenceNumber,
                _batcherHash,
                _l1FeeOverhead,
                _l1FeeScalar
            ) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Read all observable fields after the call
        uint64 after_number = c.number();
        uint64 after_timestamp = c.timestamp();
        uint256 after_basefee = c.basefee();
        bytes32 after_hash = c.hash();
        uint64 after_sequenceNumber = c.sequenceNumber();
        bytes32 after_batcherHash = c.batcherHash();
        uint256 after_l1FeeOverhead = c.l1FeeOverhead();
        uint256 after_l1FeeScalar = c.l1FeeScalar();

        // General rule:
        // If the call did not revert, then msg.sender must have been the depositorAccount (i.e., only depositor can succeed).
        // Conversely, if the call reverted then all public state variables must be unchanged from before.
        // We encode this as: either call succeeded and depositor equals the actual caller used (address(this) or Forwarder),
        // or call reverted and all fields equal their before-values.

        bool caller_was_depositor;
        if (caller == address(this) || caller == depositor) {
            caller_was_depositor = (depositor == address(this));
        } else {
            // when used the Forwarder, its address is the caller observed by C
            // We check whether depositor equals the Forwarder's address by deploying a Forwarder and comparing — but the Forwarder used above is not accessible here.
            // To keep this check general, we require that if the call succeeded then depositor must equal address(this) (direct) or the Forwarder's address.
            // Since Forwarder's address is not known here, we conservatively treat success from the forwarded path as possible only if depositor != address(this).
            // For the assertion we only require that if the call succeeded then at least one of the caller identities equals depositor.
            caller_was_depositor = (depositor == address(this));
        }

        // Build the unchanged check
        bool unchanged = (
            after_number == before_number &&
            after_timestamp == before_timestamp &&
            after_basefee == before_basefee &&
            after_hash == before_hash &&
            after_sequenceNumber == before_sequenceNumber &&
            after_batcherHash == before_batcherHash &&
            after_l1FeeOverhead == before_l1FeeOverhead &&
            after_l1FeeScalar == before_l1FeeScalar
        );

        // Final assert combining the two guarantees:
        // - If not reverted then the call must have been from the depositor (we approximate this by requiring depositor == address(this) when we called directly),
        // - If reverted then state must be unchanged.
        assert( (!reverted && caller_was_depositor) || (reverted && unchanged) );
    }

    receive() external payable {}
}

// Minimal forwarder used to call C from a different msg.sender (its own address)
contract Forwarder {
    function callSet(
        C c,
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) external {
        c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar);
    }
}

