contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // same params as setL1BlockValues; include an amount to attempt to send
    function run(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar,
        uint256 amount
    ) public payable {
        // ensure this contract has enough balance if we plan to forward Ether
        if (amount > 0) require(address(this).balance >= amount);

        // read balance before the call
        uint256 before = address(c).balance;

        bool reverted;
        // attempt the call, possibly sending Ether
        try c.setL1BlockValues{value: amount}(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read balance after the call
        uint256 after = address(c).balance;

        // General rule: the contract's balance increases by exactly 'amount' iff the call succeeded and did not revert; if it reverted then balance must be unchanged.
        // This asserts that no hidden behavior causes Ether to be lost or gained beyond the forwarded amount.
        assert(after == before + (reverted ? 0 : amount));
    }

    receive() external payable {}
}

