contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: try calling setL1BlockValues as msg.sender == this contract
    function run(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar,
        address caller // not used to change msg.sender but used to compare with depositorAccount
    ) public payable {
        require(true);

        // read observable state before the call
        uint64 before_number = c.number();
        uint64 before_timestamp = c.timestamp();
        uint256 before_basefee = c.basefee();
        bytes32 before_hash = c.hash();
        uint64 before_sequenceNumber = c.sequenceNumber();
        bytes32 before_batcherHash = c.batcherHash();
        uint256 before_l1FeeOverhead = c.l1FeeOverhead();
        uint256 before_l1FeeScalar = c.l1FeeScalar();
        address depositor = c.depositorAccount();

        // attempt the state-changing call and capture whether it reverted
        bool reverted;
        try c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After call, read observable state
        uint64 after_number = c.number();
        uint64 after_timestamp = c.timestamp();
        uint256 after_basefee = c.basefee();
        bytes32 after_hash = c.hash();
        uint64 after_sequenceNumber = c.sequenceNumber();
        bytes32 after_batcherHash = c.batcherHash();
        uint256 after_l1FeeOverhead = c.l1FeeOverhead();
        uint256 after_l1FeeScalar = c.l1FeeScalar();

        // General rule:
        // If the caller (this contract) is not equal to depositorAccount, the call must revert
        // and none of the public getters must change. If this contract equals depositorAccount,
        // the call may succeed (we do not assert specific new values), so we only assert that
        // when the depositor differs from this contract then reverted==true and all values unchanged.
        bool thisIsDepositor = (address(this) == depositor);

        assert(
            (
                thisIsDepositor
                ? true                                // if this is depositor, we do not constrain outcome here
                : (
                    reverted
                    && after_number == before_number
                    && after_timestamp == before_timestamp
                    && after_basefee == before_basefee
                    && after_hash == before_hash
                    && after_sequenceNumber == before_sequenceNumber
                    && after_batcherHash == before_batcherHash
                    && after_l1FeeOverhead == before_l1FeeOverhead
                    && after_l1FeeScalar == before_l1FeeScalar
                )
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
